 const load=async()=>{const d=await api('/api/desktop/workspace');setData(d);const source=d.draftDirty?d.draft.config:d.active.config;setCfgState(normalize(source));setHistory([]);setFuture([]);setDirty(!!d.draftDirty);setStatus(d.draftDirty?'Є збережена чернетка':'Опублікована конфігурація')};
 useEffect(()=>{load()},[]);
 if(!cfg||!data)return <div className="desk-spinner"/>;
 const apply=(next:any)=>{setHistory(h=>[...h.slice(-29),clone(cfg)]);setFuture([]);setCfgState(normalize(next));setDirty(true);setStatus('Є незбережені зміни')};
 const undo=()=>{setHistory(h=>{if(!h.length)return h;const prev=h[h.length-1];setFuture(f=>[clone(cfg),...f].slice(0,30));setCfgState(clone(prev));setDirty(true);setStatus('Є незбережені зміни');return h.slice(0,-1)})};
 const redo=()=>{setFuture(f=>{if(!f.length)return f;const next=f[0];setHistory(h=>[...h,clone(cfg)].slice(-30));setCfgState(clone(next));setDirty(true);setStatus('Є незбережені зміни');return f.slice(1)})};
 const move=(idx:number,dir:number)=>{const a=[...cfg.sidebar],j=idx+dir;if(j<0||j>=a.length)return;[a[idx],a[j]]=[a[j],a[idx]];apply({...cfg,sidebar:a.map((x:any,p:number)=>({...x,position:p}))})};
 const dropOn=(targetId:string)=>{if(!dragId||dragId===targetId)return;const a=[...cfg.sidebar],from=a.findIndex((x:any)=>x.id===dragId),to=a.findIndex((x:any)=>x.id===targetId);if(from<0||to<0)return;const [item]=a.splice(from,1);a.splice(to,0,item);setDragId('');apply({...cfg,sidebar:a.map((x:any,p:number)=>({...x,position:p}))})};
