 return <><div className="workspace-editor-head"><div><span className="desk-eyebrow">LIVE CONFIGURATION</span><h2>Редактор структури панелі керування</h2><p>Редактор працює з реальною published/draft конфігурацією. Зміни потрапляють у live продукт тільки після Publish.</p></div><div className={'workspace-save-state '+(status.startsWith('Помилка')?'error':dirty?'dirty':'ok')}>{status}</div></div>
 <div className="desk-toolbar"><button disabled={!history.length} onClick={undo}>↶ Undo</button><button disabled={!future.length} onClick={redo}>↷ Redo</button><button onClick={()=>lock(!data.draft.locked)}>{data.draft.locked?<><Lock/>Unlock</>:<><Unlock/>Lock</>}</button><button onClick={save}><Save/>Save Draft</button><button className="desk-primary" onClick={()=>setPublishPreview(true)}><Upload/>Publish</button><button onClick={download}><Download/>Export</button><label className="desk-upload"><Upload/>Import<input type="file" accept=".json,application/json" onChange={e=>importFile(e.target.files?.[0])}/></label></div>
 <div className="workspace-grid"><Panel title="Структура Desktop"><div className="workspace-list live-builder">{cfg.sidebar.map((x:any,i:number)=><div key={x.id} className={x.hidden?'hidden-item':''} draggable onDragStart={()=>setDragId(x.id)} onDragOver={e=>e.preventDefault()} onDrop={()=>dropOn(x.id)}><input className="workspace-inline-title" value={x.label||''} onChange={e=>patchItem(i,{label:e.target.value,title:e.target.value})}/><small>{x.group} · {x.id}</small><div><button title={x.hidden?'Показати':'Сховати'} onClick={()=>patchItem(i,{hidden:!x.hidden})}>{x.hidden?<EyeOff/>:<Eye/>}</button><button title="Вище" onClick={()=>move(i,-1)}>↑</button><button title="Нижче" onClick={()=>move(i,1)}>↓</button></div></div>)}</div></Panel>
 <Panel title="Live Preview"><div className="desk-segment">{(['OWNER','ADMIN','MANAGER'] as Role[]).map(r=><button key={r} className={preview===r?'active':''} onClick={()=>setPreview(r)}>{r}</button>)}</div><div className="desk-segment preview-devices"><button className={device==='desktop'?'active':''} onClick={()=>setDevice('desktop')}><Monitor/>Desktop</button><button className={device==='laptop'?'active':''} onClick={()=>setDevice('laptop')}><Monitor/>Laptop</button><button className={device==='tablet'?'active':''} onClick={()=>setDevice('tablet')}><Tablet/>iPad</button></div><div className={'workspace-preview '+device}><aside>{visibleSidebar.map((x:any)=><span key={x.id}>{x.label}</span>)}</aside><main><div className="workspace-widget-grid">{visibleWidgets.map((w:any)=><div style={{gridColumn:'span '+Math.min(12,Math.max(1,w.width||3)),minHeight:40*(w.height||1)}} key={w.id}>{w.title}</div>)}</div></main></div></Panel></div>
 <Panel title="Віджети Dashboard"><div className="workspace-widget-editor">{cfg.widgets.map((w:any,i:number)=><div key={w.id} className={w.hidden?'hidden-item':''}><input value={w.title||''} onChange={e=>patchWidget(i,{title:e.target.value})}/><select value={w.width||3} onChange={e=>patchWidget(i,{width:Number(e.target.value)})}>{[2,3,4,6,8,12].map(n=><option value={n} key={n}>{n}/12</option>)}</select><button onClick={()=>patchWidget(i,{hidden:!w.hidden})}>{w.hidden?<EyeOff/>:<Eye/>}</button><small>{w.id}</small></div>)}</div></Panel>
 <Panel title="Versions"><div className="desk-version-list">{(data.versions||[]).map((v:any)=><div key={v.id}><b>v{v.version_number}{v.is_active?' · ACTIVE':''}</b><span>{dt(v.created_at)} · {v.comment||''}</span>{!v.is_active&&<button onClick={async()=>{await post('/api/desktop/workspace/revert',{version:v.version_number});await load();onPublished()}}><RotateCcw/>Rollback</button>}</div>)}</div></Panel>
 {publishPreview&&<div className="desk-drawer-backdrop critical-modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setPublishPreview(false)}><div className="critical-modal publish-preview"><Upload/><h3>Опублікувати зміни?</h3><p>Буде змінено live Desktop layout. Draft залишиться доступним у version history.</p><ul><li>Пунктів меню: {cfg.sidebar.length}</li><li>Приховано: {cfg.sidebar.filter((x:any)=>x.hidden).length}</li><li>Віджетів: {cfg.widgets.length}</li><li>Активна версія зараз: v{data.active?.version||1}</li></ul><div><button onClick={()=>setPublishPreview(false)}>Скасувати</button><button className="desk-primary" onClick={publish}>Опублікувати</button></div></div></div>}</>
